<?php
require __DIR__ . '/bootstrap.php'; protegido();
$linhas=banco()->query('SELECT * FROM doadores ORDER BY data_cadastro DESC,id DESC')->fetchAll();
$salas=banco()->query('SELECT serie,AVG(idade) AS media FROM doadores GROUP BY serie ORDER BY serie')->fetchAll();
$total=count($linhas); $doaram=array_sum(array_column($linhas,'doou')); topo('Dashboard'); ?>
<div class="painel-topo"><div><span class="etiqueta">PAINEL DE SOLIDARIEDADE</span><h1>Olá, <?= e($_SESSION['usuario']) ?>.</h1><p>Acompanhe os gestos que estão fazendo a diferença.</p></div><form method="post" action="logout.php"><?php token(); ?><button class="secundario">Sair da conta ↗</button></form></div><section class="metricas"><article><span>Participações</span><strong><?= $total ?></strong></article><article><span>Doaram itens</span><strong><?= $doaram ?></strong></article><article><span>Ainda não doaram</span><strong><?= $total-$doaram ?></strong></article></section>
<section class="graficos"><article><h2>Média de idade por turma</h2><div class="grafico"><canvas id="idades" aria-label="Média de idade por turma" role="img"></canvas></div><ul class="resumo"><?php foreach($salas as $s): ?><li><?= e($s['serie']) ?>: <?= number_format((float)$s['media'],1,',','.') ?> anos</li><?php endforeach; ?></ul></article><article><h2>Uma corrente de contribuições</h2><div class="grafico"><canvas id="doacoes" aria-label="Comparativo de doações" role="img"></canvas></div><p><?= $doaram ?> doaram · <?= $total-$doaram ?> ainda não doaram</p></article></section>
<section class="tabela-card"><h2>Todas as participações <span class="contador"><?= $total ?></span></h2><?php if (!$linhas): ?><p>Nenhuma participação por enquanto. Os novos cadastros aparecerão aqui.</p><?php else: ?><div class="rolagem" tabindex="0" role="region" aria-label="Cadastros do bazar"><table><caption>Dados dos participantes do bazar</caption><thead><tr><th>ID</th><th>Nome</th><th>Idade</th><th>Turma</th><th>Doou?</th><th>Itens doados</th><th>Cadastro</th></tr></thead><tbody><?php foreach($linhas as $l): ?><tr><td><?= (int)$l['id'] ?></td><td><?= e($l['nome']) ?></td><td><?= (int)$l['idade'] ?></td><td><?= e($l['serie']) ?></td><td><span class="badge"><?= $l['doou'] ? 'Sim' : 'Ainda não' ?></span></td><td class="itens"><?= e($l['itens_doados'] ?: '—') ?></td><td><?= e(date('d/m/Y H:i',strtotime($l['data_cadastro']))) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
<script id="dados-graficos" type="application/json"><?= json_encode(['salas'=>array_column($salas,'serie'),'medias'=>array_map('floatval',array_column($salas,'media')),'doacoes'=>[$doaram,$total-$doaram]], JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_THROW_ON_ERROR) ?></script><script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.8/dist/chart.umd.min.js" defer></script><script src="assets/dashboard.js" defer></script><?php rodape(); ?>
